package net.officefloor.hq.app.audit;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.TreeSet;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** The audit viewer: reads what the audit file holds for a sheet; it writes nothing. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/audit")
public class AuditController {

    private final Audit audit;
    private final PersonRepository people;
    private final SheetRepository sheets;

    public AuditController(Audit audit, PersonRepository people, SheetRepository sheets) {
        this.audit = audit;
        this.people = people;
        this.sheets = sheets;
    }

    /**
     * The sheet's audit lines, newest first; with a name, only those about that person, followed by those about them
     * on each of the sheet's descendants (sheets by id, each newest first), then, when the person of that name on the sheet was transferred to it, by the lines about them from the sheet they came from, newest first.
     */
    @GetMapping
    public List<String> list(@PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @RequestParam(defaultValue = "") @Size(max = 200) String name) {
        List<String> lines = new ArrayList<>(audit.lines(sheetId, name));
        String key = name.strip();
        if (!key.isEmpty()) {
            for (String descendant : descendants(sheetId)) {
                lines.addAll(audit.lines(descendant, key));
            }
            people.findBySheetIdAndNameIgnoreCase(sheetId, key).map(Person::getOriginSheet)
                    .ifPresent(origin -> lines.addAll(audit.lines(origin, key)));
        }
        return lines;
    }

    /** The sheet's descendants, by id: the sheets naming it as parent, the ones naming those, and so on. */
    private TreeSet<String> descendants(String sheetId) {
        TreeSet<String> found = new TreeSet<>();
        Deque<String> toVisit = new ArrayDeque<>(List.of(sheetId));
        while (!toVisit.isEmpty()) {
            for (Sheet child : sheets.findByParentIdOrderByIdAsc(toVisit.poll())) {
                if (!child.getId().equals(sheetId) && found.add(child.getId())) {
                    toVisit.add(child.getId());
                }
            }
        }
        return found;
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { FigPipe } from '../../core/locale';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The audit viewer: the active sheet's audit lines exactly as the file holds them, newest first. With a name in the
// filter, only the lines about that person (name= or person= that name, case and surrounding spaces ignored), then
// those on the sheet's descendants (sheets by id, each newest first), then, for a person transferred to this sheet, the lines about them from the sheet they came from.
@Component({
  selector: 'app-audit-viewer',
  imports: [FigPipe],
  template: `
    <section aria-label="Audit">
      <h2>Audit</h2>
      <form (submit)="show($event)" aria-label="Show the audit">
        <label for="audit-filter">Person</label>
        <input
          id="audit-filter"
          data-testid="audit-filter"
          [value]="filter()"
          (input)="filter.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="audit-show">Show audit</button>
        @if (error(); as err) {
          <p role="alert" data-testid="audit-error">{{ err | fig }}</p>
        }
      </form>

      <ol aria-label="Audit lines">
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line | fig }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditViewer {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly lines = signal<readonly string[]>([]);
  protected readonly filter = signal('');
  protected readonly error = signal<string | null>(null);
  // Each press is numbered, so only the latest one's answer shows.
  private press = 0;

  constructor() {
    // A newly loaded sheet starts with the list empty.
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.press++;
        this.error.set(null);
        this.lines.set([]);
      });
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async show(e: Event): Promise<void> {
    e.preventDefault();
    this.error.set(null);
    this.lines.set([]);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const press = ++this.press;
    try {
      const l = await firstValueFrom(
        this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit`, {
          params: { name: this.filter() },
        }),
      );
      if (press === this.press) this.lines.set(l);
    } catch {
      if (press === this.press) this.error.set('Could not read the audit.');
    }
  }
}

